/* Reviewed literary excerpts; the library never changes the user's saved notes. */
(()=>{
 const style=document.createElement('link');style.rel='stylesheet';style.href='/quote-library.css?v=20261105-1';document.head.append(style);
 const base=journalView;let rows=[],nextPage=1,term='',epoch=0,busy=false;
 journalView=function(){return base().replace('<div class="account-setting-grid">','<div class="account-setting-grid"><button type="button" data-quote-library><span>'+icon('book')+'语录库</span><small>从书中读到的句子 ↗</small></button>')};
 async function api(path){const r=await fetch(path,{credentials:'same-origin'});const d=await r.json();if(!r.ok)throw new Error(d.error||'语录库暂时无法打开');return d}
 function paint(total){const box=document.querySelector('#quote-library-list');if(!box)return;box.innerHTML=rows.map(q=>`<article class="quote-library-item"><blockquote>${esc(q.quote)}</blockquote><p class="quote-library-source">${esc(q.author)} ·《${esc(q.work)}》${q.chapterTitle?' · '+esc(q.chapterTitle):''}</p><p>${esc(q.interpretation)}</p><div class="quote-library-actions"><button class="secondary" type="button" data-quote-open="${esc(q.id)}">读原文</button><button class="secondary" type="button" data-quote-chat="${esc(q.id)}">一起聊聊</button></div></article>`).join('')||'<p class="quote-library-empty">'+(term?'没有找到匹配的语录。':'小溪正在整理书库，通过复核的句子会陆续出现在这里。')+'</p>';document.querySelector('#quote-library-more').hidden=rows.length>=total;document.querySelector('#quote-library-count').textContent=total+' 条语录'}
 async function load(reset=false){if(busy&&!reset)return;const run=++epoch;busy=true;if(reset){rows=[];nextPage=1}const target=document.querySelector('#quote-library-list');const message=document.querySelector('#quote-library-error');if(!target)return;message.textContent='';const more=document.querySelector('#quote-library-more');more.disabled=true;
  try{const d=await api('/api/quotes?'+new URLSearchParams({q:term,page:String(nextPage),limit:'20'}));if(run!==epoch||!target.isConnected)return;rows.push(...d.items);nextPage++;paint(d.total)}catch(e){if(run===epoch&&target.isConnected)message.textContent=e.message}finally{if(run===epoch){busy=false;more.disabled=false}}
 }
 async function open(){epoch++;busy=false;term='';modal('<div class="quote-library-panel"><h2>语录库</h2><form id="quote-library-search"><input name="q" type="search" maxlength="100" class="search" aria-label="搜索语录" placeholder="句子、作品、作者或主题"><button class="secondary" type="submit">搜索</button></form><div class="quote-library-status"><span id="quote-library-count"></span><details><summary>整理进度</summary><p id="quote-library-progress">正在读取进度…</p></details></div><p id="quote-library-error" role="status"></p><div id="quote-library-list" aria-live="polite">正在打开语录库…</div><button class="secondary" id="quote-library-more" type="button" hidden>加载更多</button></div>');document.querySelector('#quote-library-search').addEventListener('submit',e=>{e.preventDefault();term=e.target.elements.q.value.trim();load(true)});document.querySelector('#quote-library-more').addEventListener('click',()=>load());const progress=document.querySelector('#quote-library-progress');load(true);
  try{const s=await api('/api/quotes/status');if(progress.isConnected)progress.textContent=`${s.scope==='selected'?'本次书单：':''}已分析 ${s.completedChapters||0} / ${s.totalChapters||0} 个章节，已完成 ${s.completedWorks||0} / ${s.plannedWorks||0} 部作品的分层归纳，${s.acceptedQuotes||0} 条语录通过复核。${s.jobs?.failed?'有 '+s.jobs.failed+' 个分析任务待重试。':''}`}catch(e){if(progress.isConnected)progress.textContent=e.message}
 }
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-quote-library'))return open();const id=b.dataset.quoteOpen||b.dataset.quoteChat;if(!id)return;const q=rows.find(q=>q.id===id);if(!q)return;
  const selection={workId:q.workId,title:q.work,author:q.author,chapter:q.chapter,chapterTitle:q.chapterTitle,quote:q.quote};if(b.dataset.quoteOpen){closeModal();openCitedPassage(selection).catch(e=>toast(e.message))}else{closeModal();openAssistant({page:'reading',label:'聊聊《'+q.work+'》',readingId:q.workId,readingSelection:{...selection,text:q.quote}})}
 });
 if(page==='journal')render();
})();
